function toast(msg,ms=2400){const e=$("toast");e.textContent=msg;e.classList.add("show");clearTimeout(toast.t);toast.t=setTimeout(()=>e.classList.remove("show"),ms)}
function openDialog(id){const d=$(id);if(d&&!d.open)d.showModal()}
function closeDialog(id){const d=$(id);if(d?.open)d.close()}
function openLayer(id){const e=$(id);e.classList.remove("hidden");e.setAttribute("aria-hidden","false");document.body.style.overflow="hidden"}
function closeLayer(id){const e=$(id);e.classList.add("hidden");e.setAttribute("aria-hidden","true");document.body.style.overflow=""}

async function openIdb(){
  return new Promise((resolve,reject)=>{
    const req=indexedDB.open(SNAPSHOT_DB,DB_VERSION);
    req.onupgradeneeded=()=>{
      const db=req.result;
      if(!db.objectStoreNames.contains("outbox"))db.createObjectStore("outbox",{keyPath:"id"});
      if(!db.objectStoreNames.contains("files"))db.createObjectStore("files",{keyPath:"id"});
      if(!db.objectStoreNames.contains("meta"))db.createObjectStore("meta",{keyPath:"key"});
    };
    req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);
  });
}
function idbTx(store,mode="readonly"){return state.idb.transaction(store,mode).objectStore(store)}
function idbPut(store,val){return new Promise((resolve,reject)=>{const r=idbTx(store,"readwrite").put(val);r.onsuccess=()=>resolve(val);r.onerror=()=>reject(r.error)})}
function idbDelete(store,key){return new Promise((resolve,reject)=>{const r=idbTx(store,"readwrite").delete(key);r.onsuccess=()=>resolve();r.onerror=()=>reject(r.error)})}
function idbGetAll(store){return new Promise((resolve,reject)=>{const r=idbTx(store).getAll();r.onsuccess=()=>resolve(r.result||[]);r.onerror=()=>reject(r.error)})}
function idbGet(store,key){return new Promise((resolve,reject)=>{const r=idbTx(store).get(key);r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>reject(r.error)})}

async function cacheSnapshot(){
  if(!state.idb)return;
  const snapshot={key:"snapshot",savedAt:nowIso(),sources:state.sources.filter(s=>s.type==="book"),readingProfiles:state.readingProfiles,readingCycles:state.readingCycles,readingSessions:state.readingSessions,readingEntries:state.readingEntries.map(e=>({...e,handwritingLocalUrl:undefined})),readingPaths:state.readingPaths};
  try{await idbPut("meta",snapshot)}catch{}
}
async function loadSnapshot(){
  if(!state.idb)return false;
  const x=await idbGet("meta","snapshot");if(!x)return false;
  for(const k of ["sources","readingProfiles","readingCycles","readingSessions","readingEntries","readingPaths"])state[k]=Array.isArray(x[k])?x[k]:[];
  return true;
}

async function queueOp(collectionName,docId,data,kind="set"){
  await idbPut("outbox",{id:`${collectionName}:${docId}`,collectionName,docId,data,kind,queuedAt:nowIso()});updateSyncInfo();
}
async function cloudSet(collectionName,docId,data,{silent=false}={}){
  const clean=JSON.parse(JSON.stringify(data));
  if(!state.cloudReady||!navigator.onLine){await queueOp(collectionName,docId,clean,"set");if(!silent)toast("기기에 저장했습니다. 연결되면 동기화합니다.");return false}
  try{await setDoc(doc(state.db,"users",state.user.uid,collectionName,docId),clean,{merge:true});return true}
  catch(err){console.warn("cloudSet queued",collectionName,err);await queueOp(collectionName,docId,clean,"set");if(!silent)toast("기기에 안전하게 저장했습니다. 동기화를 다시 시도합니다.");return false}
}
async function cloudDelete(collectionName,docId){
  if(!state.cloudReady||!navigator.onLine){await queueOp(collectionName,docId,null,"delete");return false}
  try{await deleteDoc(doc(state.db,"users",state.user.uid,collectionName,docId));return true}catch(err){await queueOp(collectionName,docId,null,"delete");return false}
}
async function queueFile(file){await idbPut("files",file);updateSyncInfo()}
async function uploadAsset(file){const r=storageRef(state.storage,file.path);await uploadBytes(r,file.blob,{contentType:file.contentType});return getDownloadURL(r)}
async function saveHandwritingFiles(entry){
  const d=state.handwriting.draft;if(!d?.imageBlob)return;
  const base=`users/${state.user.uid}/reading/${entry.sourceId}/${entry.id}`;
  const imageFile={id:`${entry.id}:image`,entryId:entry.id,kind:"image",path:`${base}/handwriting.webp`,blob:d.imageBlob,contentType:"image/webp"};
  entry.handwritingPending=true;entry.strokeFileUrl=null;entry.updatedAt=nowIso();
  await queueFile(imageFile);
  await queueOp("readingEntries",entry.id,JSON.parse(JSON.stringify(entry)),"set");
  void flushSync();
}
async function flushSync(){
  if(state.syncing||!state.cloudReady||!navigator.onLine||!state.idb)return;
  state.syncing=true;let doneDocs=0,doneFiles=0;
  try{
    const ops=await idbGetAll("outbox");
    for(const op of ops){try{const ref=doc(state.db,"users",state.user.uid,op.collectionName,op.docId);if(op.kind==="delete")await deleteDoc(ref);else await setDoc(ref,op.data,{merge:true});await idbDelete("outbox",op.id);doneDocs++}catch(err){console.warn("sync op failed",op,err);break}}
    const files=await idbGetAll("files"),byEntry={};
    for(const f of files){try{const url=await uploadAsset(f);(byEntry[f.entryId]??={})[f.kind==="image"?"handwritingImageUrl":"strokeFileUrl"]=url;await idbDelete("files",f.id);doneFiles++}catch(err){console.warn("sync file failed",f,err);break}}
    for(const [entryId,patch] of Object.entries(byEntry)){const e=state.readingEntries.find(x=>x.id===entryId);if(e)Object.assign(e,patch,{handwritingPending:false,updatedAt:nowIso()});await setDoc(doc(state.db,"users",state.user.uid,"readingEntries",entryId),{...patch,handwritingPending:false,updatedAt:nowIso()},{merge:true})}
    if(doneDocs||doneFiles)toast(`☁️ ${doneDocs?`기록 ${doneDocs}건`:""}${doneDocs&&doneFiles?" · ":""}${doneFiles?`필사 이미지 ${doneFiles}개`:""} 동기화되었습니다.`);
  }finally{state.syncing=false;updateSyncInfo();cacheSnapshot()}
}
async function updateSyncInfo(){if(!state.idb)return;const [ops,files]=await Promise.all([idbGetAll("outbox"),idbGetAll("files")]);const n=ops.length+files.length;if($("syncInfo"))$("syncInfo").textContent=n?`☁️ 동기화 대기 ${n}건 · 기기에 안전하게 보관 중`:state.cloudReady&&navigator.onLine?"☁️ 동기화 완료":"☁️ 오프라인 저장 중"}

async function initFirebase(){
  const app=initializeApp(FIREBASE_CONFIG),auth=getAuth(app);state.db=getFirestore(app);state.storage=getStorage(app);
  try{await setPersistence(auth,browserLocalPersistence)}catch{}
  $("googleLoginBtn").addEventListener("click",async()=>{try{await signInWithPopup(auth,new GoogleAuthProvider())}catch(err){$("authGateStatus").textContent=`로그인 실패: ${err.message}`}});
  $("signOutBtn").addEventListener("click",async()=>signOut(auth));
  onAuthStateChanged(auth,async user=>{state.user=user;if(!user){state.cloudReady=false;$("authGate").classList.remove("hidden");$("authGateStatus").textContent="생각의 텃밭에서 쓰는 Google 계정으로 연결해주세요.";return}$("authGate").classList.add("hidden");state.cloudReady=true;$("accountInfo").textContent=user.displayName||user.email||"Google 계정 연결됨";await loadCloudData();await flushSync();renderAll()});
}
async function loadCollection(name){try{const snap=await getDocs(collection(state.db,"users",state.user.uid,name));return snap.docs.map(d=>({id:d.id,...d.data()}))}catch(err){console.warn("load collection failed",name,err);return null}}
async function loadCloudData(){
  state.loading=true;const sources=await loadCollection("sources");if(sources)state.sources=sources.filter(s=>s.type==="book");else await loadSnapshot();const fragments=await loadCollection("fragments");state.fragments=fragments||[];for(const name of COLLECTIONS){const data=await loadCollection(name);if(data)state[name]=data}
  const activeRaw=localStorage.getItem(ACTIVE_SESSION_KEY);if(activeRaw){try{state.activeSession=JSON.parse(activeRaw)}catch{localStorage.removeItem(ACTIVE_SESSION_KEY)}}state.currentBookId=localStorage.getItem(CURRENT_BOOK_KEY)||chooseCurrentBookId();state.loading=false;await cacheSnapshot();updateSyncInfo();
}

function inferService(platform=""){const p=String(platform).toLowerCase();if(p.includes("밀리"))return "millie";if(p.includes("yes24")||p.includes("예스24"))return "yes24";if(p.includes("종이"))return "paper";return "other"}
function inferFormat(platform=""){const s=inferService(platform);if(s==="millie"||s==="yes24")return "ebook";if(s==="paper")return "paper";if(String(platform).includes("오디오"))return "audiobook";return "ebook"}
function sourceById(id){return state.sources.find(x=>x.id===id)}
function profileById(sourceId){return state.readingProfiles.find(x=>x.sourceId===sourceId)}
function getProfile(sourceId){const real=profileById(sourceId);if(real)return real;const s=sourceById(sourceId);if(!s)return null;return {id:`virtual:${sourceId}`,sourceId,status:s.status==="done"?"completed":"reading",format:inferFormat(s.platform),service:inferService(s.platform),currentLocator:"",startedAt:s.createdAt||"",lastReadAt:"",completedAt:s.status==="done"?(s.updatedAt||""):null,_virtual:true}}
function ensureProfile(sourceId){let p=profileById(sourceId);if(p)return p;const v=getProfile(sourceId);p={...v,id:uid(),_virtual:undefined,createdAt:nowIso(),updatedAt:nowIso()};state.readingProfiles.push(p);cloudSet("readingProfiles",p.id,p,{silent:true});return p}
function readingBooks(){return state.sources.filter(s=>getProfile(s.id)?.status==="reading")}
function chooseCurrentBookId(){const books=readingBooks();books.sort((a,b)=>new Date(getProfile(b.id)?.lastReadAt||b.updatedAt||0)-new Date(getProfile(a.id)?.lastReadAt||a.updatedAt||0));return books[0]?.id||state.sources[0]?.id||null}
function setCurrentBook(id){state.currentBookId=id;localStorage.setItem(CURRENT_BOOK_KEY,id);renderRead()}
function serviceText(p){return SERVICE_LABELS[p?.service]||FORMAT_LABELS[p?.format]||"독서"}
function coverHtml(s,cls="hero-cover"){return s?.image?`<img class="${cls}" src="${esc(s.image)}" alt="${esc(s.title)} 표지" />`:`<div class="${cls} placeholder">📕</div>`}
function setView(view){state.currentView=view;$$('.view').forEach(v=>v.classList.toggle('active',v.dataset.view===view));$$('.nav-btn').forEach(b=>b.classList.toggle('on',b.dataset.viewTarget===view));if(view==="read")renderRead();if(view==="library")renderLibrary();if(view==="timeline")renderTimeline();if(view==="stats")renderStats()}
function renderAll(){renderRead();renderLibrary();renderTimeline();renderStats();renderTimelineBookOptions();renderPaths()}

function renderRead(){
  const box=$("readHero");if(state.loading){box.innerHTML=`<div class="empty-hero"><p>서재를 불러오고 있어요…</p></div>`;return}
  if(state.activeSession&&!state.activeSession.endedAt){const s=sourceById(state.activeSession.sourceId);box.innerHTML=`<div class="read-hero-inner"><div class="notice" style="margin-bottom:18px">진행 중이던 독서가 있어요.</div>${coverHtml(s)}<h2 class="hero-title">${esc(s?.title||"읽던 책")}</h2><p class="hero-author">${esc(s?.creator||"")}</p><button class="btn primary block start-btn" data-resume-session type="button">▶ 독서 계속하기</button><button class="text-btn switch-book" data-abandon-session type="button">종료 처리하기</button></div>`;return}
  const s=sourceById(state.currentBookId)||sourceById(chooseCurrentBookId());if(!s){box.innerHTML=`<div class="empty-hero"><div class="empty-icon">📚</div><h2>읽을 책을 골라볼까요?</h2><p>생각의 텃밭에 등록한 책이 있으면 같은 서재에서 자동으로 불러옵니다.</p><button class="btn primary" data-open-book-search type="button">＋ 책 추가</button></div>`;return}
  state.currentBookId=s.id;const p=getProfile(s.id),isPhysical=p?.format==="paper"||p?.format==="pdf",locator=safeText(p?.currentLocator);
  box.innerHTML=`<div class="read-hero-inner">${coverHtml(s)}<h2 class="hero-title">${esc(s.title)}</h2><p class="hero-author">${esc(s.creator||"")}</p><span class="hero-service">${esc(serviceText(p))}</span>${isPhysical&&locator?`<div class="hero-locator"><small>지난번 위치</small><strong>${esc(nextLocator(locator,p.format))}</strong></div>`:p?.lastReadAt?`<div class="hero-locator"><small>최근 독서</small><strong style="font-size:1rem">${esc(relativeDate(p.lastReadAt))}</strong></div>`:""}<button class="btn primary block start-btn" data-start-book="${esc(s.id)}" type="button">▶ 읽기 시작</button><button class="text-btn switch-book" data-open-book-picker type="button">다른 책 선택 ›</button></div>`;
}
function nextLocator(locator,format){if(format!=="paper"&&format!=="pdf")return locator;const m=String(locator).match(/(?:p\.\s*)?(\d+)/i);return m?`p.${Number(m[1])+1}부터`:locator}
function relativeDate(v){const d=new Date(v),today=new Date();today.setHours(0,0,0,0);const x=new Date(d);x.setHours(0,0,0,0);const days=Math.round((today-x)/86400000);return days===0?"오늘":days===1?"어제":`${days}일 전`}

function renderLibrary(){const statuses=["reading","wishlist","paused","completed","dnf"];$("libraryStatusChips").innerHTML=statuses.map(x=>`<button class="chip-btn ${state.libraryStatus===x?"on":""}" data-library-status="${x}" type="button">${STATUS_LABELS[x]}</button>`).join("");$("libraryBooksPanel").classList.toggle("hidden",state.libraryMode!=="books");$("pathsPanel").classList.toggle("hidden",state.libraryMode!=="paths");if(state.libraryMode!=="books")return;const q=safeText($("librarySearch")?.value).toLowerCase(),books=state.sources.filter(s=>getProfile(s.id)?.status===state.libraryStatus).filter(s=>!q||`${s.title} ${s.creator}`.toLowerCase().includes(q));$("libraryGrid").innerHTML=books.length?books.map(s=>{const p=getProfile(s.id);return `<article class="book-card" data-open-book="${esc(s.id)}">${coverHtml(s,"book-card-cover")}<h3>${esc(s.title)}</h3><p>${esc(s.creator||"")}</p><div class="book-card-meta"><span class="mini-tag">${esc(serviceText(p))}</span>${p?.currentLocator?`<span class="mini-tag">${esc(p.currentLocator)}</span>`:""}</div></article>`}).join(""):`<div class="empty-card">${STATUS_LABELS[state.libraryStatus]} 책이 없습니다.</div>`}
function renderPaths(){const box=$("pathsList");if(!box)return;box.innerHTML=state.readingPaths.length?state.readingPaths.map(p=>{const ids=p.sourceIds||[],done=ids.filter(id=>getProfile(id)?.status==="completed").length,pct=ids.length?Math.round(done/ids.length*100):0;return `<article class="path-card"><h3>${esc(p.title)}</h3>${p.description?`<p>${esc(p.description)}</p>`:""}<p>${done} / ${ids.length}</p><div class="path-progress"><span style="width:${pct}%"></span></div></article>`}).join(""):`<div class="empty-card">아직 Reading Path가 없습니다.</div>`}
function bookMetrics(sourceId){const ss=state.readingSessions.filter(s=>s.sourceId===sourceId&&s.endedAt),entries=state.readingEntries.filter(e=>e.sourceId===sourceId),mins=ss.reduce((a,b)=>a+(Number(b.finalDurationMinutes)||0),0),days=new Set(ss.map(s=>localDate(s.startedAt))).size;return {mins,days,sessions:ss.length,entries,quotes:entries.filter(e=>safeText(e.quoteText||e.confirmedText)).length,handwriting:entries.filter(e=>e.inputMethod==="handwriting").length,thoughts:entries.filter(e=>safeText(e.thought)).length}}
function openBookDetail(id){state.detailBookId=id;state.detailTab="timeline";renderBookDetail();openLayer("bookDetail")}
function renderBookDetail(){const s=sourceById(state.detailBookId);if(!s)return;const p=getProfile(s.id),m=bookMetrics(s.id),detailTimeline=renderTimelineHtml({bookId:s.id,embedded:true});$("bookDetailBody").innerHTML=`<div class="detail-hero">${coverHtml(s,"detail-cover")}<div class="detail-meta"><h2>${esc(s.title)}</h2><p>${esc(s.creator||"")}</p><div class="detail-tags"><span class="mini-tag">${esc(STATUS_LABELS[p.status])}</span><span class="mini-tag">${esc(serviceText(p))}</span>${p.currentLocator?`<span class="mini-tag">${esc(p.currentLocator)}</span>`:""}</div></div></div><button class="btn primary block detail-start" data-start-book="${esc(s.id)}" type="button">▶ 읽기 시작</button><div class="detail-metrics"><div class="detail-metric"><small>총 독서시간</small><strong>${fmtMinutes(m.mins)}</strong></div><div class="detail-metric"><small>읽은 날</small><strong>${m.days}일</strong></div></div><div id="bookMoreMenu" class="more-menu hidden"><button class="btn" data-edit-profile="${esc(s.id)}" type="button">읽기 설정 수정</button><button class="btn" data-complete-book="${esc(s.id)}" type="button">◉ 완독 처리</button><button class="btn" data-print-book="${esc(s.id)}" type="button">📄 이 책 기록 PDF / 인쇄</button></div><div class="segmented detail-tabs"><button class="seg ${state.detailTab==="timeline"?"on":""}" data-detail-tab="timeline" type="button">기록</button><button class="seg ${state.detailTab==="stats"?"on":""}" data-detail-tab="stats" type="button">통계</button></div><div id="detailTabBody">${state.detailTab==="timeline"?detailTimeline:renderBookStatsHtml(s.id)}</div>`}
function renderBookStatsHtml(id){const m=bookMetrics(id);return `<div class="stats-summary"><div class="stat-card"><small>총 시간</small><strong>${fmtMinutes(m.mins)}</strong></div><div class="stat-card"><small>세션</small><strong>${m.sessions}회</strong></div><div class="stat-card"><small>필사</small><strong>${m.handwriting}</strong></div><div class="stat-card"><small>생각</small><strong>${m.thoughts}</strong></div></div>`}

function ensureCycle(sourceId){let c=state.readingCycles.find(x=>x.sourceId===sourceId&&!x.completedAt);if(c)return c;const prior=state.readingCycles.filter(x=>x.sourceId===sourceId);c={id:uid(),sourceId,sequence:prior.length+1,format:getProfile(sourceId)?.format||"ebook",service:getProfile(sourceId)?.service||"other",startedAt:nowIso(),completedAt:null,finalReflection:"",oneLineReflection:"",rereadWanted:false,createdAt:nowIso(),updatedAt:nowIso()};state.readingCycles.push(c);cloudSet("readingCycles",c.id,c,{silent:true});return c}
async function startSession(sourceId){if(state.activeSession&&!state.activeSession.endedAt){toast("이미 진행 중인 독서가 있어요.");return}const s=sourceById(sourceId);if(!s)return;const p=ensureProfile(sourceId);if(p.status!=="reading"){p.status="reading";p.updatedAt=nowIso();await cloudSet("readingProfiles",p.id,p,{silent:true})}const c=ensureCycle(sourceId),session={id:uid(),sourceId,cycleId:c.id,startedAt:nowIso(),endedAt:null,rawDurationMinutes:0,measuredDurationMinutes:0,finalDurationMinutes:0,durationAdjusted:false,startLocator:p.currentLocator||"",endLocator:"",format:p.format,service:p.service,readingFeel:"",sessionNote:"",pausedMs:0,pauseStartedAt:null,pauses:[],createdAt:nowIso(),updatedAt:nowIso()};state.activeSession=session;localStorage.setItem(ACTIVE_SESSION_KEY,JSON.stringify(session));await cloudSet("readingSessions",session.id,session,{silent:true});openSession(session)}
function openSession(session=state.activeSession){if(!session)return;state.activeSession=session;const s=sourceById(session.sourceId);$("sessionBookTitle").textContent=s?.title||"독서";$("sessionService").textContent=serviceText(getProfile(session.sourceId));openLayer("sessionLayer");startTimer()}
