function normalizeGenre(raw=""){const x=raw.toLowerCase();if(/소설|문학/.test(x))return "소설";if(/에세이/.test(x))return "에세이";if(/인문|철학/.test(x))return "인문·철학";if(/사회|정치/.test(x))return "사회·정치";if(/역사/.test(x))return "역사";if(/심리/.test(x))return "심리";if(/경제|경영/.test(x))return "경제·경영";if(/과학|기술|컴퓨터/.test(x))return "과학·기술";if(/예술|문화/.test(x))return "예술·문화";if(/자기계발/.test(x))return "자기계발";if(/육아|교육/.test(x))return "육아·교육";return "기타"}
function getThoughtGardenApiKeys(){try{return JSON.parse(localStorage.getItem("thoughtGarden_apiKeys")||"{}")}catch{return {}}}
async function googleBooksSearch(q){try{const keys=getThoughtGardenApiKeys(),key=keys.youtube||keys.google||keys.googleBooks||keys.googleApiKey||"",url=new URL("https://www.googleapis.com/books/v1/volumes");url.searchParams.set("q",q);url.searchParams.set("maxResults","20");if(key)url.searchParams.set("key",key);const r=await fetch(url);if(!r.ok)return [];const j=await r.json();return (j.items||[]).map(item=>{const v=item.volumeInfo||{},isbn=(v.industryIdentifiers||[]).find(x=>x.type==="ISBN_13")?.identifier||(v.industryIdentifiers||[])[0]?.identifier||"";return {title:safeText(v.title),creator:safeText((v.authors||[]).join(", ")),publisher:safeText(v.publisher),image:(v.imageLinks?.thumbnail||v.imageLinks?.smallThumbnail||"").replace(/^http:/,"https:"),isbn13:isbn,categoryName:safeText((v.categories||[]).join(" > ")),pubDate:v.publishedDate||"",externalLink:v.infoLink||"",provider:"Google Books"}}).filter(x=>x.title)}catch{return []}}
function dedupeBookResults(items){const seen=new Set();return items.filter(x=>{const key=(String(x.isbn13||"").replace(/\D/g,"")||`${x.title}|${x.creator}`).toLowerCase();if(seen.has(key))return false;seen.add(key);return true})}
function openBookSearch(){openDialog("bookSearchDialog");setTimeout(()=>$("bookSearchInput").focus(),50)}
async function runBookSearch(){const q=safeText($("bookSearchInput").value);if(!q)return;const box=$("bookSearchResults");box.innerHTML=`<div class="helper">검색 중…</div>`;const local=state.sources.filter(s=>`${s.title} ${s.creator}`.toLowerCase().includes(q.toLowerCase())).slice(0,6);let api=[];try{const r=await fetch(`${BOOK_SEARCH_PROXY}?q=${encodeURIComponent(q)}`),j=await r.json();if(j.ok)api=(j.items||[]).map(x=>({title:safeText(x.title),creator:safeText(x.author),publisher:safeText(x.publisher),image:x.cover||"",isbn13:x.isbn13||x.isbn||"",categoryName:safeText(x.categoryName),pubDate:x.pubDate||"",externalLink:x.link||"",provider:"Aladin"}))}catch(err){console.warn(err)}if(api.length<8){const google=await googleBooksSearch(q);api=dedupeBookResults([...api,...google])}box.innerHTML=(local.length?`<div class="eyebrow" style="margin:10px 0 4px">이미 내 서재에 있음</div>${local.map(s=>bookSearchRow(s,true)).join("")}`:"")+(api.length?`<div class="eyebrow" style="margin:14px 0 4px">검색 결과</div>${api.map((x,i)=>bookSearchRow({...x,_index:i},false)).join("")}`:`<div class="empty-card">검색 결과가 없습니다.</div>`);state.bookApiResults=api}
function bookSearchRow(x,existing){return `<div class="search-book-row">${x.image?`<img src="${esc(x.image)}" alt="">`:`<div style="width:48px;height:68px;background:var(--panel2);border-radius:7px;display:grid;place-items:center">📕</div>`}<div><h3>${esc(x.title)}</h3><p>${esc(x.creator||"")}${x.publisher?` · ${esc(x.publisher)}`:""}</p></div><button class="btn ${existing?"soft":"primary"}" ${existing?`data-open-existing-book="${esc(x.id)}"`:`data-add-api-book="${x._index}"`} type="button">${existing?"열기":"추가"}</button></div>`}
async function addApiBook(index){const x=state.bookApiResults?.[index];if(!x)return;const dup=x.isbn13&&state.sources.find(s=>String(s.isbn13||"").replace(/\D/g,"")===String(x.isbn13).replace(/\D/g,""));if(dup){closeDialog("bookSearchDialog");openBookDetail(dup.id);toast("이미 등록된 책을 열었습니다.");return}const s={id:uid(),type:"book",status:"active",title:x.title,creator:x.creator,platform:"",image:x.image,isbn13:x.isbn13,provider:x.provider,externalLink:x.externalLink,rawCategories:x.categoryName?[x.categoryName]:[],primaryGenre:normalizeGenre(x.categoryName),publisher:x.publisher,pubDate:x.pubDate,createdAt:nowIso(),updatedAt:nowIso()};state.sources.push(s);await cloudSet("sources",s.id,s);closeDialog("bookSearchDialog");openProfile(s.id);renderAll()}

function openProfile(sourceId){const p=getProfile(sourceId),s=sourceById(sourceId);$("profileSourceId").value=sourceId;$("profileDialogTitle").textContent=s?.title||"읽기 설정";$("profileStatus").value=p?.status||"reading";$("profileFormat").value=p?.format||"ebook";$("profileService").value=p?.service||"other";$("profileLocator").value=p?.currentLocator||"";openDialog("profileDialog")}
async function saveProfile(){const id=$("profileSourceId").value,p=ensureProfile(id);Object.assign(p,{status:$("profileStatus").value,format:$("profileFormat").value,service:$("profileService").value,currentLocator:safeText($("profileLocator").value),updatedAt:nowIso()});if(!p.startedAt&&p.status==="reading")p.startedAt=nowIso();if(p.status==="completed"&&!p.completedAt)p.completedAt=nowIso();await cloudSet("readingProfiles",p.id,p);const s=sourceById(id);if(s){s.status=p.status==="completed"?"done":"active";s.updatedAt=nowIso();await cloudSet("sources",s.id,s,{silent:true})}closeDialog("profileDialog");state.currentBookId=id;localStorage.setItem(CURRENT_BOOK_KEY,id);renderAll();if(state.detailBookId===id)renderBookDetail()}
function openComplete(sourceId){state.detailBookId=sourceId;const s=sourceById(sourceId),m=bookMetrics(sourceId),c=state.readingCycles.find(x=>x.sourceId===sourceId&&!x.completedAt)||ensureCycle(sourceId);$("completeBookTitle").textContent=`${s?.title||"이 책"} 완독`;$("completeSummary").innerHTML=`${c.startedAt?displayDateFull(c.startedAt):""}<br><b>${fmtMinutes(m.mins)}</b> · ${m.days}일 동안 읽음`;$("finalReflection").value=c.finalReflection||"";$("oneLineReflection").value=c.oneLineReflection||"";$("rereadWanted").checked=!!c.rereadWanted;openDialog("completeDialog")}
