function renderTimelineBookOptions(){const sel=$("timelineBookFilter"),v=sel.value;sel.innerHTML=`<option value="">전체 책</option>`+state.sources.slice().sort((a,b)=>a.title.localeCompare(b.title,"ko")).map(s=>`<option value="${esc(s.id)}">${esc(s.title)}</option>`).join("");sel.value=v}
function timelineEvents(bookId=""){const linked=new Set(state.readingEntries.map(e=>e.linkedFragmentId).filter(Boolean)),events=[];for(const s of state.readingSessions.filter(x=>x.endedAt&&(!bookId||x.sourceId===bookId)))events.push({type:"session",date:s.startedAt,session:s,entries:state.readingEntries.filter(e=>e.sessionId===s.id)});for(const e of state.readingEntries.filter(e=>!e.sessionId&&(!bookId||e.sourceId===bookId)))events.push({type:"entry",date:e.createdAt,entry:e});for(const f of state.fragments.filter(f=>f.sourceId&&sourceById(f.sourceId)&&!linked.has(f.id)&&(!bookId||f.sourceId===bookId)))events.push({type:"legacy",date:f.date||f.createdAt,fragment:f});for(const c of state.readingCycles.filter(c=>c.completedAt&&(!bookId||c.sourceId===bookId)))events.push({type:"complete",date:c.completedAt,cycle:c});return events.sort((a,b)=>new Date(b.date)-new Date(a.date))}
function entryMatches(e,filter){if(filter==="all")return true;if(filter==="quote")return !!safeText(e.quoteText||e.confirmedText);if(filter==="handwriting")return e.inputMethod==="handwriting";if(filter==="thought")return !!safeText(e.thought);return true}
function renderEntryHtml(e,{legacy=false}={}){const quote=safeText(e.quoteText||e.confirmedText||e.externalText),thought=safeText(e.thought);return `<div class="timeline-entry" ${!legacy?`data-edit-entry="${esc(e.id)}"`:""}>${e.locator?`<div class="entry-locator">${esc(e.locator)}</div>`:""}${e.handwritingImageUrl?`<img class="handwriting-preview" src="${esc(e.handwritingImageUrl)}" alt="필사 원본">`:e.inputMethod==="handwriting"&&e.handwritingPending?`<div class="notice">✍ 필사 원본 동기화 중</div>`:""}${quote?`<div class="entry-quote">${esc(quote)}</div>`:""}${thought?`<div class="entry-thought">${esc(thought)}</div>`:""}${legacy?`<span class="legacy-badge">생각의 텃밭에서 남긴 기록</span>`:""}</div>`}
function renderEvent(ev,filter="all"){
  if(ev.type==="session"){const s=sourceById(ev.session.sourceId),entries=ev.entries.filter(e=>entryMatches(e,filter));if(filter!=="all"&&!entries.length)return "";return `<div class="timeline-card"><article class="timeline-session"><div class="timeline-session-head">${s?.image?`<img class="timeline-thumb" src="${esc(s.image)}" alt="">`:`<div class="timeline-thumb"></div>`}<div><h3>${esc(s?.title||"책")}</h3><p>${timeText(ev.session.startedAt)}${ev.session.endedAt?` – ${timeText(ev.session.endedAt)}`:""} · ${fmtMinutes(ev.session.finalDurationMinutes)} · ${esc(SERVICE_LABELS[ev.session.service]||"")}</p></div></div>${entries.map(e=>renderEntryHtml(e)).join("")}${ev.session.sessionNote&&filter==="all"?`<div class="session-note">“${esc(ev.session.sessionNote)}”</div>`:""}</article></div>`}
  if(ev.type==="entry"){if(!entryMatches(ev.entry,filter))return "";const s=sourceById(ev.entry.sourceId);return `<div class="timeline-card"><article class="timeline-session"><div class="timeline-session-head"><div><h3>${esc(s?.title||"책")}</h3><p>독서 기록</p></div></div>${renderEntryHtml(ev.entry)}</article></div>`}
  if(ev.type==="legacy"){const f=ev.fragment,e={sourceId:f.sourceId,locator:f.locator,externalText:f.externalText,thought:f.thought};if(filter==="handwriting")return "";if(filter==="quote"&&!safeText(f.externalText))return "";if(filter==="thought"&&!safeText(f.thought))return "";const s=sourceById(f.sourceId);return `<div class="timeline-card"><article class="timeline-session"><div class="timeline-session-head"><div><h3>${esc(s?.title||"책")}</h3><p>예전 독서 기록</p></div></div>${renderEntryHtml(e,{legacy:true})}</article></div>`}
  if(ev.type==="complete"&&filter==="all"){const c=ev.cycle,s=sourceById(c.sourceId),m=bookMetrics(c.sourceId);return `<div class="timeline-card"><div class="completion-event"><div class="complete-mark">◉</div><h3>${esc(s?.title||"책")} 완독</h3><p>${c.startedAt?`${displayDateFull(c.startedAt)} → `:""}${displayDateFull(c.completedAt)}<br>${fmtMinutes(m.mins)} · ${m.days}일 독서</p>${c.oneLineReflection?`<div class="entry-thought">${esc(c.oneLineReflection)}</div>`:""}</div></div>`}return "";
}
function renderTimelineHtml({bookId="",embedded=false}={}){const filter=embedded?"all":state.timelineFilter,events=timelineEvents(bookId||(!embedded?$("timelineBookFilter")?.value||"":"")),groups=new Map();for(const ev of events){const html=renderEvent(ev,filter);if(!html)continue;const d=localDate(ev.date);if(!groups.has(d))groups.set(d,[]);groups.get(d).push(html)}if(!groups.size)return `<div class="empty-card">아직 보여줄 독서 기록이 없습니다.</div>`;return [...groups.entries()].map(([d,items])=>`<section class="day-group"><div class="day-title">${displayDate(`${d}T12:00:00`)}</div>${items.join("")}</section>`).join("")}
function renderTimeline(){$("timelineList").innerHTML=renderTimelineHtml()}

function rangeStart(range){const n=new Date();if(range==="week"){const d=n.getDay()||7;n.setHours(0,0,0,0);n.setDate(n.getDate()-d+1);return n}if(range==="month")return new Date(n.getFullYear(),n.getMonth(),1);if(range==="year")return new Date(n.getFullYear(),0,1);return new Date(0)}
function sessionsInRange(){const st=rangeStart(state.statsRange);return state.readingSessions.filter(s=>s.endedAt&&new Date(s.startedAt)>=st)}
function entriesInRange(){const st=rangeStart(state.statsRange);return state.readingEntries.filter(e=>new Date(e.createdAt)>=st)}
function renderStats(){const ss=sessionsInRange(),es=entriesInRange(),mins=ss.reduce((a,b)=>a+(Number(b.finalDurationMinutes)||0),0),days=new Set(ss.map(s=>localDate(s.startedAt))).size,complete=state.readingCycles.filter(c=>c.completedAt&&new Date(c.completedAt)>=rangeStart(state.statsRange)).length;$("statsSummary").innerHTML=`<div class="stat-card"><small>독서시간</small><strong>${fmtMinutes(mins)}</strong></div><div class="stat-card"><small>독서한 날</small><strong>${days}일</strong></div><div class="stat-card"><small>세션</small><strong>${ss.length}회</strong></div><div class="stat-card"><small>완독</small><strong>${complete}권</strong></div>`;const daily=buildDailySeries(ss),weekday=[0,1,2,3,4,5,6].map(d=>({label:["일","월","화","수","목","금","토"][d],value:ss.filter(s=>new Date(s.startedAt).getDay()===d).reduce((a,b)=>a+(+b.finalDurationMinutes||0),0)})),timeBuckets=[{label:"아침",test:h=>h>=5&&h<11},{label:"낮",test:h=>h>=11&&h<17},{label:"저녁",test:h=>h>=17&&h<22},{label:"심야",test:h=>h>=22||h<5}].map(b=>({label:b.label,value:ss.filter(s=>b.test(new Date(s.startedAt).getHours())).reduce((a,x)=>a+(+x.finalDurationMinutes||0),0)})),genres=genreSeries(ss),activity=[{label:"문장",value:es.filter(e=>safeText(e.quoteText||e.confirmedText)).length},{label:"필사",value:es.filter(e=>e.inputMethod==="handwriting").length},{label:"생각",value:es.filter(e=>safeText(e.thought)).length}];$("statsCharts").innerHTML=chartCard("독서시간 추이","시간의 흐름에 따라 읽은 분량이 어떻게 달라졌는지 봅니다.",daily,"분")+hbarCard("요일별 독서 패턴","어떤 요일에 책을 더 자주 붙잡는지 봅니다.",weekday,"분")+hbarCard("시간대별 독서","읽기가 잘 시작되는 시간대를 봅니다.",timeBuckets,"분")+hbarCard("장르 분포","독서시간 기준입니다.",genres,"분")+hbarCard("남긴 기록","문장 · 필사 · 생각이 얼마나 쌓였는지 봅니다.",activity,"개")+`<div class="chart-card"><h3>Thought Garden으로 이어진 생각</h3><p>책을 읽다 생긴 내 생각만 공유합니다.</p><strong style="font-family:var(--serif);font-size:1.5rem">${es.filter(e=>e.linkedFragmentId).length}개</strong></div>`}
function buildDailySeries(ss){const out=[],days=state.statsRange==="week"?7:state.statsRange==="month"?Math.min(31,new Date().getDate()):12;if(state.statsRange==="year"||state.statsRange==="all"){const n=new Date();for(let i=days-1;i>=0;i--){const d=new Date(n.getFullYear(),n.getMonth()-i,1),ym=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`;out.push({label:`${d.getMonth()+1}월`,value:ss.filter(s=>localDate(s.startedAt).startsWith(ym)).reduce((a,b)=>a+(+b.finalDurationMinutes||0),0)})}}else{const n=new Date();for(let i=days-1;i>=0;i--){const d=new Date(n);d.setDate(n.getDate()-i);const key=d.toLocaleDateString("en-CA");out.push({label:`${d.getMonth()+1}/${d.getDate()}`,value:ss.filter(s=>localDate(s.startedAt)===key).reduce((a,b)=>a+(+b.finalDurationMinutes||0),0)})}}return out}
function genreSeries(ss){const map={};for(const s of ss){const book=sourceById(s.sourceId),g=book?.primaryGenre||"기타";map[g]=(map[g]||0)+(+s.finalDurationMinutes||0)}return Object.entries(map).map(([label,value])=>({label,value})).sort((a,b)=>b.value-a.value)}
function chartCard(title,desc,data,unit){const max=Math.max(1,...data.map(x=>x.value));return `<section class="chart-card"><h3>${title}</h3><p>${desc}</p><div class="bar-chart">${data.map(x=>`<div class="bar-col" title="${esc(x.label)} ${x.value}${unit}"><span style="height:${Math.max(2,x.value/max*120)}px"></span><small>${esc(x.label)}</small></div>`).join("")}</div></section>`}
function hbarCard(title,desc,data,unit){const max=Math.max(1,...data.map(x=>x.value));return `<section class="chart-card"><h3>${title}</h3><p>${desc}</p><div class="hbar-list">${data.map(x=>`<div class="hbar-row"><span>${esc(x.label)}</span><div class="hbar-track"><div class="hbar-fill" style="width:${x.value/max*100}%"></div></div><span class="hbar-value">${x.value}${unit}</span></div>`).join("")}</div></section>`}

function searchRecords(q){q=q.toLowerCase();const results=[];for(const e of state.readingEntries){const s=sourceById(e.sourceId),text=`${s?.title||""} ${s?.creator||""} ${e.locator||""} ${e.quoteText||""} ${e.confirmedText||""} ${e.thought||""}`.toLowerCase();if(text.includes(q))results.push({kind:"entry",date:e.createdAt,e,s})}for(const f of state.fragments){const s=sourceById(f.sourceId);if(!s)continue;const text=`${s.title} ${s.creator||""} ${f.externalText||""} ${f.thought||""} ${f.locator||""}`.toLowerCase();if(text.includes(q))results.push({kind:"legacy",date:f.date||f.createdAt,f,s})}return results.sort((a,b)=>new Date(b.date)-new Date(a.date)).slice(0,100)}
function renderSearch(){const q=safeText($("globalSearchInput").value);if(!q){$("globalSearchResults").innerHTML=`<div class="helper">검색어를 입력하세요.</div>`;return}const rr=searchRecords(q);$("globalSearchResults").innerHTML=rr.length?rr.map(r=>`<div class="search-result-row"><div><h3>${esc(r.s?.title||"책")}</h3><p>${displayDateFull(r.date)}${(r.e?.locator||r.f?.locator)?` · ${esc(r.e?.locator||r.f?.locator)}`:""}</p><p style="margin-top:5px;color:var(--text)">${esc((r.e?.quoteText||r.e?.thought||r.f?.externalText||r.f?.thought||"").slice(0,120))}</p></div></div>`).join(""):`<div class="empty-card">검색 결과가 없습니다.</div>`}
function openPathDialog(){$("pathTitle").value="";$("pathDescription").value="";$("pathBookChoices").innerHTML=state.sources.map(s=>`<label class="choice-row"><input type="checkbox" value="${esc(s.id)}"><span>${esc(s.title)}<small style="display:block;color:var(--muted)">${esc(s.creator||"")}</small></span></label>`).join("");openDialog("pathDialog")}
async function savePath(){const title=safeText($("pathTitle").value);if(!title)return toast("Path 이름을 적어주세요.");const sourceIds=$$("#pathBookChoices input:checked").map(x=>x.value),p={id:uid(),title,description:safeText($("pathDescription").value),sourceIds,createdAt:nowIso(),updatedAt:nowIso()};state.readingPaths.push(p);await cloudSet("readingPaths",p.id,p);closeDialog("pathDialog");renderPaths();toast("Reading Path를 만들었습니다.")}

function buildPrintData(scopeBookId=""){return timelineEvents(scopeBookId)}
function openExport(bookId=""){state.exportBookId=bookId||"";$("exportScope").value=bookId?"currentBook":"all";openDialog("exportDialog")}
function doPrint(){const bookId=$("exportScope").value==="currentBook"?(state.exportBookId||state.detailBookId||state.currentBookId):"",events=buildPrintData(bookId),books=bookId?[sourceById(bookId)]:state.sources;let html=`<section class="print-cover"><div style="font-size:26pt">📖</div><h1>독서의 정원</h1><p>${bookId?esc(sourceById(bookId)?.title||""):"나의 독서 기록"}</p><p>${displayDateFull(nowIso())}</p></section>`;if(bookId)html+=printBookSection(bookId,events);else for(const s of books){const es=events.filter(e=>(e.session?.sourceId||e.entry?.sourceId||e.fragment?.sourceId||e.cycle?.sourceId)===s.id);if(es.length)html+=printBookSection(s.id,es)}$("printRoot").innerHTML=html;closeDialog("exportDialog");setTimeout(()=>window.print(),80)}
function printBookSection(id,events){const s=sourceById(id),m=bookMetrics(id);let html=`<section class="print-section"><div class="print-book-head">${s?.image?`<img src="${esc(s.image)}" alt="">`:""}<div><h2>${esc(s?.title||"책")}</h2><div>${esc(s?.creator||"")}</div><div class="print-meta">총 독서시간 ${fmtMinutes(m.mins)} · 독서일 ${m.days}일 · 세션 ${m.sessions}회</div></div></div>`,groups=new Map();for(const ev of events){const d=localDate(ev.date);if(!groups.has(d))groups.set(d,[]);groups.get(d).push(ev)}for(const [d,items] of groups){html+=`<div class="print-day">${displayDateFull(`${d}T12:00:00`)}</div>`;for(const ev of items){if(ev.type==="session"&&$("printSession").checked)html+=`<div class="print-session">${timeText(ev.session.startedAt)} – ${timeText(ev.session.endedAt)} · ${fmtMinutes(ev.session.finalDurationMinutes)}${ev.session.sessionNote?`<br>${esc(ev.session.sessionNote)}`:""}</div>`;const entries=ev.type==="session"?ev.entries:ev.type==="entry"?[ev.entry]:[];for(const e of entries)html+=printEntry(e);if(ev.type==="legacy")html+=printEntry({locator:ev.fragment.locator,quoteText:ev.fragment.externalText,thought:ev.fragment.thought});if(ev.type==="complete")html+=`<div class="print-complete">◉ 완독<br>${esc(ev.cycle.oneLineReflection||ev.cycle.finalReflection||"")}</div>`}}html+=`</section>`;return html}
function printEntry(e){const quote=safeText(e.quoteText||e.confirmedText),thought=safeText(e.thought);if(!quote&&!thought)return "";return `<div class="print-entry">${e.locator?`<div class="print-meta">${esc(e.locator)}</div>`:""}${$("printHandwriting").checked&&e.handwritingImageUrl?`<img class="print-handwriting" src="${esc(e.handwritingImageUrl)}" alt="필사">`:""}${$("printQuote").checked&&quote?`<div class="print-quote">${esc(quote)}</div>`:""}${$("printThought").checked&&thought?`<div class="print-thought">${esc(thought)}</div>`:""}</div>`}
function downloadBlob(blob,name){const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},800)}
function backupJson(){const data={version:1,exportedAt:nowIso(),sources:state.sources,readingProfiles:state.readingProfiles,readingCycles:state.readingCycles,readingSessions:state.readingSessions,readingEntries:state.readingEntries,readingPaths:state.readingPaths};downloadBlob(new Blob([JSON.stringify(data,null,2)],{type:"application/json"}),`reading-garden-backup-${localDate()}.json`)}
async function restoreJson(file){try{const data=JSON.parse(await file.text());if(!confirm("백업 데이터를 현재 독서의 정원에 합칠까요? 같은 ID는 백업 내용으로 갱신됩니다."))return;for(const name of ["sources",...COLLECTIONS])for(const item of Array.isArray(data[name])?data[name]:[]){const arr=state[name],i=arr.findIndex(x=>x.id===item.id);if(i>=0)arr[i]=item;else arr.push(item);await cloudSet(name,item.id,item,{silent:true})}await cacheSnapshot();renderAll();toast("JSON 백업을 복원했습니다.")}catch(err){toast(`복원 실패: ${err.message}`)}}

function bindEvents(){
  document.addEventListener("click",async e=>{
    const nav=e.target.closest("[data-view-target]");if(nav)return setView(nav.dataset.viewTarget);const close=e.target.closest("[data-close-dialog]");if(close)return closeDialog(close.dataset.closeDialog);const layer=e.target.closest("[data-close-layer]");if(layer)return closeLayer(layer.dataset.closeLayer);const start=e.target.closest("[data-start-book]");if(start){if(!$("bookDetail").classList.contains("hidden"))closeLayer("bookDetail");return startSession(start.dataset.startBook)}if(e.target.closest("[data-resume-session]"))return openSession();if(e.target.closest("[data-abandon-session]"))return openEndSession();if(e.target.closest("[data-open-book-picker]")){renderBookPicker();return openDialog("bookPickerDialog")}if(e.target.closest("[data-open-book-search]"))return openBookSearch();const pick=e.target.closest("[data-pick-book]");if(pick){setCurrentBook(pick.dataset.pickBook);closeDialog("bookPickerDialog");return}const ob=e.target.closest("[data-open-book]");if(ob)return openBookDetail(ob.dataset.openBook);const os=e.target.closest("[data-open-existing-book]");if(os){closeDialog("bookSearchDialog");return openBookDetail(os.dataset.openExistingBook)}const api=e.target.closest("[data-add-api-book]");if(api)return addApiBook(Number(api.dataset.addApiBook));const st=e.target.closest("[data-library-status]");if(st){state.libraryStatus=st.dataset.libraryStatus;return renderLibrary()}const lm=e.target.closest("[data-library-mode]");if(lm){state.libraryMode=lm.dataset.libraryMode;$$('[data-library-mode]').forEach(b=>b.classList.toggle('on',b===lm));return renderLibrary()}const ef=e.target.closest("[data-entry-filter]");if(ef){state.timelineFilter=ef.dataset.entryFilter;$$('[data-entry-filter]').forEach(b=>b.classList.toggle('on',b===ef));return renderTimeline()}const rg=e.target.closest("[data-range]");if(rg){state.statsRange=rg.dataset.range;$$('[data-range]').forEach(b=>b.classList.toggle('on',b===rg));return renderStats()}const dt=e.target.closest("[data-detail-tab]");if(dt){state.detailTab=dt.dataset.detailTab;return renderBookDetail()}const ep=e.target.closest("[data-edit-profile]");if(ep)return openProfile(ep.dataset.editProfile);const cb=e.target.closest("[data-complete-book]");if(cb)return openComplete(cb.dataset.completeBook);const pb=e.target.closest("[data-print-book]");if(pb)return openExport(pb.dataset.printBook);const ee=e.target.closest("[data-edit-entry]");if(ee){const entry=state.readingEntries.find(x=>x.id===ee.dataset.editEntry);if(entry)return openRecord({entry,fromSession:false})}
  });
  $("addBookBtn").onclick=openBookSearch;$("runBookSearchBtn").onclick=runBookSearch;$("bookSearchInput").addEventListener("keydown",e=>{if(e.key==="Enter")runBookSearch()});$("librarySearch").addEventListener("input",renderLibrary);$("timelineBookFilter").addEventListener("change",renderTimeline);$("openSettings").onclick=()=>openDialog("settingsDialog");$("newPathBtn").onclick=openPathDialog;$("savePathBtn").onclick=savePath;$("bookMoreBtn").onclick=()=>$("bookMoreMenu")?.classList.toggle("hidden");$("sessionBackBtn").onclick=()=>{closeLayer("sessionLayer");renderRead()};$("openRecordBtn").onclick=()=>openRecord({fromSession:true});$("pauseSessionBtn").onclick=togglePause;$("endSessionBtn").onclick=openEndSession;$("finishSessionBtn").onclick=finishSession;$("saveEntryBtn").onclick=saveEntry;$("deleteEntryBtn").onclick=deleteCurrentEntry;$("openHandwritingBtn").onclick=openHandwriting;$("closeHandwritingBtn").onclick=()=>{closeLayer("handwritingLayer");openDialog("recordDialog")};
  $$('[data-pen-width]').forEach(b=>b.onclick=()=>{state.handwriting.width=Number(b.dataset.penWidth);state.handwriting.eraser=false;$$('[data-pen-width]').forEach(x=>x.classList.toggle('on',x===b));$("eraserBtn").classList.remove("on")});$("eraserBtn").onclick=()=>{state.handwriting.eraser=!state.handwriting.eraser;$("eraserBtn").classList.toggle("on",state.handwriting.eraser);if(state.handwriting.eraser)$$('[data-pen-width]').forEach(x=>x.classList.remove('on'))};$("undoStrokeBtn").onclick=()=>{state.handwriting.strokes.pop();redrawWriting()};$("convertHandwritingBtn").onclick=convertHandwriting;$("redoHandwritingBtn").onclick=()=>{closeDialog("ocrDialog");openHandwriting()};$("confirmOcrBtn").onclick=confirmOcr;$$('.feel-btn').forEach(b=>b.onclick=()=>{state.selectedFeel=b.dataset.feel;$$('.feel-btn').forEach(x=>x.classList.toggle('on',x===b))});$("saveProfileBtn").onclick=saveProfile;$("saveCompleteBtn").onclick=saveComplete;$("timelineSearchBtn").onclick=()=>{openDialog("searchDialog");setTimeout(()=>$("globalSearchInput").focus(),50)};$("globalSearchInput").addEventListener("input",renderSearch);$("timelineExportBtn").onclick=()=>openExport();$("printBtn").onclick=doPrint;$("jsonBackupBtn").onclick=backupJson;$("jsonRestoreInput").addEventListener("change",e=>{const f=e.target.files?.[0];if(f)restoreJson(f);e.target.value=""});window.addEventListener("online",()=>{toast("인터넷에 연결되었습니다. 동기화를 확인합니다.");flushSync()});window.addEventListener("offline",()=>{toast("오프라인입니다. 기록은 기기에 안전하게 저장됩니다.");updateSyncInfo()});
}
function renderBookPicker(){const books=readingBooks();$("bookPickerList").innerHTML=books.length?books.map(s=>{const p=getProfile(s.id);return `<div class="picker-row">${s.image?`<img src="${esc(s.image)}" alt="">`:`<div style="width:48px;height:68px;background:var(--panel2);border-radius:7px"></div>`}<div><h3>${esc(s.title)}</h3><p>${esc(s.creator||"")} · ${esc(serviceText(p))}${p.currentLocator?` · ${esc(p.currentLocator)}`:""}</p></div><button class="btn soft" data-pick-book="${esc(s.id)}" type="button">선택</button></div>`}).join(""):`<div class="empty-card">읽는 중인 책이 없습니다.</div>`}
async function boot(){state.idb=await openIdb();await loadSnapshot();bindEvents();setupHandwriting();renderAll();updateSyncInfo();initFirebase().catch(err=>{console.error(err);$("authGate").classList.remove("hidden");$("authGateStatus").textContent=`Firebase 연결 실패: ${err.message}`})}
boot();
